export default function (wf) {
  const version = process.versions.node;
  console.log(`javascript ${version}`);
  wf.setState("fromJs", version);
  return version;
}

export default function (wf: {
  getState(key: string): unknown;
  getReturn(name: string): string;
}) {
  const version = process.versions.node;
  console.log(`typescript ${version}`);
  return { javascript: wf.getReturn("js"), typescript: version, state: wf.getState("fromJs") };
}
